package tv.luna.player.data.security

import androidx.datastore.core.DataStore
import androidx.datastore.preferences.core.Preferences
import androidx.datastore.preferences.core.booleanPreferencesKey
import androidx.datastore.preferences.core.edit
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.flow.first
import kotlinx.coroutines.withContext
import javax.crypto.SecretKeyFactory
import javax.crypto.spec.PBEKeySpec

/*
 * First-run activation. Only one-way fingerprints of the accepted codes are kept here (PBKDF2), never the codes
 * themselves, so they can't be read back out of the app or its source.
 */

private val P = arrayOf(
    "",
    "",
    "",
    "",
    "",
    "",
    "",
    "",
    "",
    "",
    "",
    "",
    "",
    "",
    "",
    "",
    "",
    "",
    "",
    "",
    "",
    "",
    "",
    "",
    "",
    "",
    "",
    "",
    "",
    "",
    "",
    "",
    "",
    "",
    "",
    "",
    "",
    "",
    "",
    ""
)

private fun table(): Pair<ByteArray, Set<String>> {
    val all = P.joinToString("") { it.reversed() }
    val salt = all.substring(0, 32).chunked(2).map { it.toInt(16).toByte() }.toByteArray()
    return salt to all.substring(32).chunked(64).toSet()
}

/** Capitals, spaces, dashes and dots don't matter. */
fun normaliseCode(s: String) = s.uppercase().filter { it.isLetterOrDigit() }

class Activation(private val prefs: DataStore<Preferences>) {
    private val key = booleanPreferencesKey("activated")

    suspend fun isActivated(): Boolean = prefs.data.first()[key] == true

    suspend fun markActivated() { prefs.edit { it[key] = true } }

    /** True (and remembered) when [code] is one of the accepted ones. */
    suspend fun tryCode(code: String): Boolean = withContext(Dispatchers.Default) {
        val n = normaliseCode(code)
        if (n.length < 6) return@withContext false
        val (salt, accepted) = table()
        val spec = PBEKeySpec(n.toCharArray(), salt, 20_000, 256)
        val hash = SecretKeyFactory.getInstance("PBKDF2WithHmacSHA256").generateSecret(spec).encoded.joinToString("") { "%02x".format(it) }
        (hash in accepted).also { ok -> if (ok) markActivated() }
    }
}
